(window.StillReady||Promise.resolve()).then(() => {
  'use strict';
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const D=window.StillData, ctx=window.StillContext||{server:false};
  const {positions,account,cents,positionValue,positionGain,purchaseValue,positionDay}=D;
  const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=(n,d=2,currency=D.currency)=>n==null||Number.isNaN(n)?'—':new Intl.NumberFormat('en-US',{style:'currency',currency,minimumFractionDigits:d,maximumFractionDigits:d}).format(n);
  const signedMoney=(n,currency)=>n==null||Number.isNaN(n)?'—':`${n>0?'+':n<0?'−':''}${money(Math.abs(n),2,currency)}`;
  const pct=(n,sign=true)=>n==null||!Number.isFinite(n)?'—':`${sign&&n>0?'+':n<0?'−':''}${Math.abs(n).toFixed(2)}%`;
  const day=h=>h.previous==null?null:(h.price/h.previous-1)*100, growth=h=>h.cost==null?null:(h.price/h.cost-1)*100;
  const fmtDate=iso=>iso?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(iso+'T00:00:00Z')):'—';
  const fmtQty=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:6});
  const price=h=>money(h.price,2,h.currency);
  const qty=h=>`${fmtQty(h.qty)} ${!D.live||h.sector==='Stocks & ETFs'?'shares':'units'}`;
  // Wording that differs between the demo and imported IBKR reports.
  const L=D.live?{asOf:fmtDate(D.asOf),move:D.previousDate?`since ${fmtDate(D.previousDate)}`:'',noMove:'No earlier report',dayHead:'Change',vsPrevious:`since ${fmtDate(D.previousDate)}`,noPrevious:'No earlier report to compare',cost:'Average cost',costNote:'IBKR cost basis, incl. fees',sinceCost:'vs cost'}
    :{asOf:'21 Oct 2026',move:'today',noMove:'—',dayHead:'Today',vsPrevious:'vs previous close',noPrevious:'—',cost:'Average purchase',costNote:'6 Jan 2026',sinceCost:'since purchase'};
  const tone=n=>n>0?'positive':n<0?'negative':'muted';
  const paths={
    portfolio:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    discover:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>',
    research:'<path d="M5 4h11l3 3v13H5Z"/><path d="M9 8h4M9 12h6M9 16h6"/>',
    news:'<rect x="3" y="4" width="18" height="16" rx="1"/><path d="M7 8h4v4H7zM14 8h3M14 12h3M7 16h10"/>',
    shield:'<path d="m12 3 8 3v6c0 4-5 7.5-8 9-3-1.5-8-5-8-9V6Z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    panel:'<rect x="3" y="4" width="18" height="16" rx="1"/><path d="M9 4v16"/>',
    send:'<path d="m6 12 6-6 6 6M12 6v14"/>',
    stock:'<path d="M3 17 8 12l4 3 8-10M15 5h5v5"/>',
    arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',
    back:'<path d="M19 12H5m6-6-6 6 6 6"/>',
    star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',
    down:'<path d="m6 9 6 6 6-6"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
  };
  const icon=(name,extra='')=>`<svg viewBox="0 0 24 24" fill="${extra.includes('fill')?'currentColor':'none'}" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.stock}</svg>`;
  $$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
  const read=(storage,key,fallback)=>{try{return JSON.parse(storage.getItem(key))??fallback;}catch{return fallback;}};
  const save=(storage,key,value)=>{try{storage.setItem(key,JSON.stringify(value));return true;}catch{return false;}};
  let watchlist=read(localStorage,'still.watchlist',['NVDA','MSFT','AAPL']);
  watchlist=Array.isArray(watchlist)?[...new Set(watchlist.filter(s=>positions.some(h=>h.symbol===s)))]:['NVDA','MSFT','AAPL'];
  let openStocks=read(sessionStorage,'still.openTabs',[]);
  openStocks=Array.isArray(openStocks)?[...new Set(openStocks.filter(s=>positions.some(h=>h.symbol===s)))]:[];
  const state={queries:{instruments:'',research:''},tab:'portfolio',settings:'ibkr',news:'feed',symbol:null,section:'overview',period:'YTD',stockPeriods:{},research:'exposure',shock:20,query:'',listMode:'holdings',sector:'all',gainers:false,sort:'default',direction:1,collapsed:false,scroll:{},stockSections:{},stockOrigins:{},unsupported:''};
  let globalIndex=0,globalItems=[],toastTimer,dragging=false;
  const periods=['1D','1W','1M','3M','YTD','ALL'];
  const technology=D.live?[]:positions.filter(h=>['Technology','Semiconductors'].includes(h.sector));
  const techValue=technology.reduce((s,h)=>s+positionValue(h),0);
  state.shockSet=D.live?positions.slice(0,1).map(h=>h.symbol):positions.filter(h=>h.sector==='Semiconductors').map(h=>h.symbol);
  const shocked=()=>positions.filter(h=>state.shockSet.includes(h.symbol));
  const shockedCents=()=>shocked().reduce((s,h)=>s+cents(positionValue(h)),0);
  const sectors=[...new Set(positions.map(h=>h.sector))];
  const tabKey=()=>state.tab==='stock'?`stock/${state.symbol}`:state.tab;
  const names={portfolio:'Portfolio',discover:'Discover',research:'Research',news:'News',settings:'Settings'};
  const find=s=>positions.find(h=>h.symbol===s);
  function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
  function route(){return state.tab==='stock'?`stock/${state.symbol}/${state.section}`:state.tab==='research'?`research/${state.research}`:state.tab==='news'?`news/${state.news}`:state.tab==='settings'?`settings/${state.settings}`:state.tab;}
  function readRoute(){const parts=location.hash.slice(1).split('/');if(parts[0]==='stock'&&find(parts[1]))return{tab:'stock',symbol:parts[1],section:['overview','position','research','news'].includes(parts[2])?parts[2]:'overview'};if(parts[0]==='news')return{tab:'news',news:['feed','search','sources'].includes(parts[1])?parts[1]:'feed'};if(parts[0]==='settings')return{tab:'settings',settings:['search','security','privacy'].includes(parts[1])?parts[1]:'ibkr'};if(parts[0]==='research')return{tab:'research',research:['exposure','scenario','performance'].includes(parts[1])?parts[1]:'exposure'};return{tab:['portfolio','discover','settings'].includes(parts[0])?parts[0]:'portfolio'};}
  function persistTabs(){save(sessionStorage,'still.openTabs',openStocks);}
  function navigate(next,options={}){
    state.scroll[tabKey()]=$('#workspace-panel').scrollTop;
    const previousScope=state.tab==='research'?'research':'instruments';
    const nextScope=next==='research'?'research':'instruments';
    state.queries[previousScope]=state.query;
    if(previousScope!==nextScope)state.query=state.queries[nextScope]||'';
    if(next.startsWith('stock/')){const [,symbol,section]=next.split('/');if(!find(symbol))return;if(state.tab!=='stock')state.stockOrigins[symbol]=state.tab;state.tab='stock';state.symbol=symbol;state.section=section||state.stockSections[symbol]||'overview';if(!openStocks.includes(symbol)){openStocks.push(symbol);persistTabs();}}
    else{state.tab=next;if(next==='news'&&options.news)state.news=options.news;if(next==='settings'&&options.settings)state.settings=options.settings;if(next==='research'&&options.research)state.research=options.research;}
    if(options.resetScroll)state.scroll[tabKey()]=0;
    if(!options.history){const hash='#'+route();if(location.hash!==hash)history.pushState(null,'',hash);}
    renderShell();renderBrowser();renderCanvas();
    $('#workspace-panel').scrollTop=state.scroll[tabKey()]||0;
    if(options.focus)$('#workspace-panel').focus({preventScroll:true});
    if(state.tab==='stock')requestAnimationFrame(()=>$('.document-tab[aria-selected=true]')?.scrollIntoView({block:'nearest',inline:'nearest'}));
  }
  function renderShell(){
    $('#app').dataset.tab=state.tab;
    const tabs=[{key:'portfolio',label:'Portfolio',icon:'portfolio'},{key:'discover',label:'Discover',icon:'discover'},{key:'research',label:'Research',icon:'research'},{key:'news',label:'News',icon:'news'},...openStocks.map(symbol=>({key:`stock/${symbol}`,label:symbol,icon:'stock',close:symbol}))];
    if(state.tab==='settings')tabs.push({key:'settings',label:'Settings',icon:'shield',close:'settings'});
    $('#document-tabs').innerHTML=tabs.map(t=>{const active=t.key===tabKey();const id='tab-'+t.key.replace('/','-');return`<div class="tab-item ${t.close?'closable':''} ${active?'active':''}" role="presentation"><button class="document-tab" id="${escape(id)}" role="tab" aria-selected="${active}" aria-controls="workspace-panel" tabindex="${active?0:-1}" data-go="${escape(t.key)}">${icon(t.icon)}${escape(t.label)}</button>${t.close?`<button class="close-tab" data-close="${escape(t.close)}" aria-label="Close ${escape(t.label)} tab" tabindex="${active?0:-1}">×</button>`:''}</div>`;}).join('');
    $('#workspace-panel').setAttribute('aria-labelledby','tab-'+tabKey().replace('/','-'));
    $('#workspace-panel').setAttribute('aria-label',(state.tab==='stock'?find(state.symbol).name:names[state.tab])+' workspace');
    $$('.rail-button').forEach(b=>{const current=b.dataset.go===state.tab||state.tab==='stock'&&b.dataset.go==='portfolio';if(current)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
    document.title=`${state.tab==='stock'?`${state.symbol} · ${find(state.symbol).name}`:names[state.tab]} — Still`;
  }
  function currentList(){return positions.filter(h=>`${h.symbol} ${h.name} ${h.sector}`.toLowerCase().includes(state.query.toLowerCase().trim())&&(state.listMode!=='watchlist'||watchlist.includes(h.symbol))&&(state.sector==='all'||h.sector===state.sector)&&(!state.gainers||day(h)>0));}
  function renderBrowser(){
    const isResearch=state.tab==='research',isDiscover=state.tab==='discover';
    $('#browser-title').textContent=isResearch?'Research desk':isDiscover?'Discover':'Your instruments';
    const input=$('#instrument-search');input.placeholder=isResearch?'Find a research topic…':isDiscover?'Search companies or symbols…':'Search holdings…';input.setAttribute('aria-label',isResearch?'Search research topics':'Search instrument list');
    if(input.value!==state.query)input.value=state.query;
    if(isResearch){$('#browser-controls').innerHTML='<div class="browser-tabs"><button role="tab" aria-selected="true" tabindex="0">Portfolio studies</button></div>';const q=state.query.toLowerCase();const studies=[['exposure','Concentration & exposure','Sectors and direct positions'],['scenario',D.live?'Holding price shock':'Semiconductor scenario','Adjust an explicit price shock'],['performance','Purchase-to-current growth','Rank returns since purchase']].filter(s=>s.slice(1).join(' ').toLowerCase().includes(q));$('#browser-count').textContent=String(studies.length);$('#instrument-list').innerHTML=studies.length?studies.map(([id,title,sub])=>`<button class="study-row ${state.research===id?'selected':''}" data-research="${id}"><strong>${title}</strong><small>${sub}</small></button>`).join(''):'<p class="empty-state">No matching studies. Try “exposure” or clear your search.</p>';}
    else{
      $('#browser-controls').innerHTML=`<div class="browser-tabs" role="tablist" aria-label="Instrument list scope"><button role="tab" data-list="holdings" aria-selected="${state.listMode==='holdings'}" tabindex="${state.listMode==='holdings'?0:-1}">${isDiscover?'All companies':'Holdings'}</button><button role="tab" data-list="watchlist" aria-selected="${state.listMode==='watchlist'}" tabindex="${state.listMode==='watchlist'?0:-1}">Watchlist</button></div>${isDiscover?`<label class="browser-sector">Sector<select id="browser-sector" aria-label="Filter instruments by sector"><option value="all">All sectors</option>${sectors.map(s=>`<option value="${escape(s)}" ${state.sector===s?'selected':''}>${escape(s)}</option>`).join('')}</select></label><div class="list-chips"><button data-gainers="false" class="${!state.gainers?'active':''}">All moves</button><button data-gainers="true" class="${state.gainers?'active':''}">Up today</button></div>`:''}`;
      renderInstrumentRows();
    }
    $('#browser-total').innerHTML=isResearch?`<span>Scope</span><strong>${D.live?'IBKR portfolio':'Demo portfolio'} · ${escape(D.currency)}</strong>`:`<span>${state.listMode==='watchlist'?'Following':'Portfolio value'}</span><strong class="num">${state.listMode==='watchlist'?`${watchlist.length} companies`:money(account.value)}</strong>`;
  }
  function renderInstrumentRows(){const list=currentList();$('#browser-count').textContent=`${list.length} ${list.length===1?'company':'companies'}`;$('#instrument-list').innerHTML=list.length?list.map(h=>`<button class="instrument-row ${state.tab==='stock'&&state.symbol===h.symbol?'selected':''}" data-open="${escape(h.symbol)}" aria-label="Open ${escape(h.name)} in a tab"><span><span class="instrument-symbol">${escape(h.symbol)}</span><span class="instrument-name">${escape(h.name)}</span></span><span class="instrument-numbers num"><span class="instrument-price">${price(h)}</span><span class="instrument-day ${tone(day(h))}">${pct(day(h))}</span></span>${watchlist.includes(h.symbol)?`<span class="instrument-watch" title="On watchlist">${icon('star')}</span>`:''}</button>`).join(''):'<div class="empty-state">No companies match these filters.<button class="text-button" data-clear>Clear search & filters</button></div>';}
  function periodsHtml(p,scope){return`<div class="periods" aria-label="${scope==='portfolio'?'Portfolio':'Stock'} chart period">${periods.map(v=>`<button data-period="${v}" data-period-scope="${scope}" aria-pressed="${v===p}" class="${v===p?'active':''}">${v}</button>`).join('')}</div>`;}
  function metric(label,value,note='',lead=false){return`<div class="metric ${lead?'lead':''}"><span>${label}</span><strong class="num">${value}</strong>${note?`<small>${note}</small>`:''}</div>`;}
  function amountWithCents(n){const [whole,fraction]=money(n).split('.');return`${whole}<span class="cents">.${fraction}</span>`;}
  function title(name,sub,actions=''){return`<header class="canvas-title"><div><h1>${escape(name)}</h1>${sub?`<p>${escape(sub)}</p>`:''}</div>${actions?`<div class="title-actions">${actions}</div>`:''}</header>`;}
  function sortHead(key,label,numeric=true){const selected=state.sort===key;return`<th class="${numeric?'num':''}" aria-sort="${selected?(state.direction===1?'ascending':'descending'):'none'}"><button data-sort="${key}">${label}${selected?icon('down'):''}</button></th>`;}
  function tableRows(list,discover=false){
    const by=f=>(a,b)=>(f(a)??-1e15)-(f(b)??-1e15);
    const comparators={name:(a,b)=>a.name.localeCompare(b.name),price:by(h=>h.price),day:by(day),value:by(positionValue),gain:by(growth)};
    if(comparators[state.sort])list=[...list].sort((a,b)=>comparators[state.sort](a,b)*state.direction);
    return list.map(h=>`<tr class="asset-row" data-open="${escape(h.symbol)}"><td><button class="asset-identity" data-open="${escape(h.symbol)}" aria-label="Open ${escape(h.name)} in a tab"><span class="asset-ticker">${escape(h.symbol)}</span><span class="asset-company">${escape(h.name)}</span></button></td><td class="num" data-mobile="price">${price(h)}<span class="cell-sub">${discover&&h.exchange?escape(h.exchange):`Price · ${escape(h.currency)}`}</span></td><td class="num ${tone(day(h))}" data-mobile="day">${pct(day(h))}<span class="cell-sub">${h.previous==null?L.noMove:`${signedMoney(h.price-h.previous,h.currency)} ${L.move}`}</span></td>${discover?`<td data-mobile="sector">${escape(h.sector)}</td><td class="num" data-mobile="watch"><button class="table-action" data-watch="${escape(h.symbol)}" aria-label="${watchlist.includes(h.symbol)?'Remove':'Add'} ${escape(h.symbol)} ${watchlist.includes(h.symbol)?'from':'to'} watchlist" aria-pressed="${watchlist.includes(h.symbol)}">${icon('star',watchlist.includes(h.symbol)?'fill="currentColor"':'')}</button></td>`:`<td class="num" data-mobile="value">${money(positionValue(h))}<span class="cell-sub">${qty(h)}</span></td><td class="num" data-mobile="gain">${signedMoney(positionGain(h))}<span class="cell-sub">${growth(h)==null?'Cost not in report':`${pct(growth(h))} ${L.sinceCost}`}</span></td>`}</tr>`).join('');
  }
  function holdingsTable(discover=false){const list=currentList();return`<div class="table-frame"><table aria-label="${discover?'Discover companies':'Portfolio holdings'}"><thead><tr>${sortHead('name',discover?'Company':'Holding',false)}${sortHead('price','Price')}${sortHead('day',L.dayHead)}${discover?'<th>Sector</th><th class="num">Follow</th>':sortHead('value','Position value')+sortHead('gain','Price return')}</tr></thead><tbody>${list.length?tableRows(list,discover):`<tr><td colspan="5"><div class="empty-state">No companies match these filters.<button class="text-button" data-clear>Clear search & filters</button></div></td></tr>`}</tbody></table></div><p class="table-count">${list.length} of ${positions.length} ${D.live?'holdings':'companies'} · ${D.live?`Values in ${escape(D.currency)} · IBKR report of ${L.asOf}`:'Prices in USD · Synthetic snapshot'}</p>`;}
  function dataBanner(){
    const notes=[];
    if(ctx.noData)notes.push(`<div class="data-banner">${icon('info')}<p>You’re looking at demo data. ${ctx.viewError?escape(ctx.viewError):'Import your first IBKR report to see your own portfolio.'}</p><button class="button" data-go="settings">Import from IBKR</button></div>`);
    const counts=D.reconciliation?.counts;
    if(D.live&&counts?.fail)notes.push(`<div class="data-banner warning">${icon('info')}<p>${counts.fail} reconciliation ${counts.fail===1?'check':'checks'} failed. The numbers below come straight from IBKR’s report, but review the differences.</p><button class="button" data-go="settings">Review</button></div>`);
    D.warnings.forEach(w=>notes.push(`<div class="data-banner warning">${icon('info')}<p>${escape(w)}</p></div>`));
    return notes.join('');
  }
  function portfolioFinding(){
    if(!D.live)return`<div class="inline-finding">${icon('info')}<p><strong>${pct(techValue/account.value*100,false)}</strong> in direct technology and semiconductor holdings.</p><button class="text-button" data-research="exposure">Explore exposure ${icon('arrow')}</button></div>`;
    const top=positions[0];
    return top?`<div class="inline-finding">${icon('info')}<p><strong>${pct(positionValue(top)/account.value*100,false)}</strong> in your largest holding, ${escape(top.symbol)}.</p><button class="text-button" data-research="exposure">Explore exposure ${icon('arrow')}</button></div>`:'';
  }
  function dayMetric(){
    if(!D.live)return metric('Today’s movement',signedMoney(account.day),`${pct(account.day/(account.value-account.day)*100)} vs previous close`);
    if(account.day==null)return metric('Since previous report','—',D.previousDate?'Some holdings are new':'Needs reports for two dates');
    return metric('Since previous report',signedMoney(account.day),`${pct(account.day/(account.value-account.day)*100)} since ${fmtDate(D.previousDate)}`);
  }
  function chartSection(){
    if(!D.live)return`<section class="section" aria-labelledby="portfolio-chart-title"><div class="section-header"><div><h2 id="portfolio-chart-title">Portfolio value over time</h2><p class="subline" id="portfolio-period-change"></p></div>${periodsHtml(state.period,'portfolio')}</div><div id="main-chart" class="chart-wrap" aria-label="Illustrative portfolio chart"></div><p class="chart-caption"><span>Synthetic history · As of 21 Oct 2026</span><span>Cost basis includes unchanged cash</span></p></section>`;
    const enough=D.history.length>=2;
    return`<section class="section" aria-labelledby="portfolio-chart-title"><div class="section-header"><div><h2 id="portfolio-chart-title">Portfolio value over time</h2><p class="subline" id="portfolio-period-change"></p></div></div>${enough?'<div id="main-chart" class="chart-wrap" aria-label="Portfolio value from imported reports"></div>':`<div class="chart-empty"><p>History appears once Still has reports for two or more dates. Daily syncs add one point a day; importing history fills earlier dates.</p><button class="text-button" data-go="settings">Import history ${icon('arrow')}</button></div>`}<p class="chart-caption"><span>IBKR report values · ${D.history.length} ${D.history.length===1?'date':'dates'} · As of ${L.asOf}</span><span>${escape(D.currency)} · Includes cash</span></p></section>`;
  }
  function renderPortfolio(){const subtitle=D.live?`IBKR · ${positions.length} ${positions.length===1?'position':'positions'} · ${D.currency} · As of ${L.asOf}`:'Personal account · 8 positions · USD';return`${title('Portfolio',subtitle,positions.length?`<button class="button" data-research="scenario">${icon('research')}Test a scenario</button>`:'')}${dataBanner()}<section class="summary-strip" aria-label="Portfolio totals">${metric('Portfolio value',amountWithCents(account.value),'Holdings + cash',true)}${dayMetric()}${metric('Unrealized gain',signedMoney(account.gain),account.gain==null?'Cost basis not in report':`${pct(account.gain/account.basis*100)} on ${D.live?'cost basis':'invested capital'}`)}${metric('Available cash',money(account.cash),`${pct(account.cash/account.value*100,false)} of portfolio`)}</section>${chartSection()}${portfolioFinding()}<section class="section" aria-labelledby="holdings-title"><div class="section-header"><h2 id="holdings-title">Holdings</h2><button class="text-button" data-go="discover">Find & filter ${D.live?'holdings':'companies'} ${icon('arrow')}</button></div><div id="main-holdings">${holdingsTable()}</div></section>`;}
  function renderDiscover(){return`${title('Discover',D.live?`${positions.length} holdings from your IBKR report · ${D.currency}`:'8 companies in your demo universe · USD')}${dataBanner()}<div class="discovery-tools"><label class="discovery-search">${icon('search')}<input id="discover-search" type="search" placeholder="Search companies, symbols or sectors…" aria-label="Search Discover companies" value="${escape(state.query)}"></label><select id="discover-sector" aria-label="Discover sector filter"><option value="all">All sectors</option>${sectors.map(s=>`<option ${state.sector===s?'selected':''}>${escape(s)}</option>`).join('')}</select></div><div class="subtabs" role="tablist" aria-label="Discover scope"><button role="tab" data-list="holdings" aria-selected="${state.listMode==='holdings'}" tabindex="${state.listMode==='holdings'?0:-1}">All companies</button><button role="tab" data-list="watchlist" aria-selected="${state.listMode==='watchlist'}" tabindex="${state.listMode==='watchlist'?0:-1}">Watchlist</button></div><div class="section-header"><h2>Companies</h2><button class="button" id="main-gainers" aria-pressed="${state.gainers}" data-gainers="${!state.gainers}">${D.live?'Up since previous report':'Up today'}</button></div><div id="main-discover">${holdingsTable(true)}</div><p class="detail-note">${D.live?'Discover lists the holdings in your imported IBKR reports. A market-wide screener needs a separate market-data provider.':'This is a synthetic universe, not a live market screener. No price, fundamental or news feeds are connected.'}</p>`;}
  function stockMetrics(h){return`<div class="stock-metrics">${metric('Your position',money(positionValue(h)),qty(h))}${metric(L.cost,h.cost==null?'—':money(h.cost,2,h.currency),L.costNote)}${metric('Unrealized gain',signedMoney(positionGain(h)),growth(h)==null?'Cost basis not in report':pct(growth(h))+' '+L.sinceCost)}${metric('Portfolio weight',pct(positionValue(h)/account.value*100,false),'Includes portfolio cash')}</div>`;}
  function stockResearch(h){
    if(!D.live)return`<section class="research-question"><h2 class="question-title">${escape(h.name)}: your position in context</h2><p>${h.qty} shares bought at ${money(h.cost)} now have a synthetic price of ${money(h.price)}. The position accounts for ${pct(positionValue(h)/account.value*100,false)} of your portfolio.</p></section><div class="research-answer"><div><strong class="answer-number num">${pct(growth(h))}</strong><span class="answer-caption">Price return since your demo purchase</span></div><div class="answer-side num">${signedMoney(positionGain(h))}<br><span class="small">Unrealized gain · USD</span></div></div><div class="findings-grid"><section class="finding-block"><h3>Exposure</h3><p>${escape(h.name)} is classified as ${escape(h.sector.toLowerCase())} in this demo. ${h.symbol==='VTI'?'No look-through holdings are available for this ETF.':'Sector classification is illustrative.'}</p><button class="text-button" data-research="exposure">View portfolio exposure ${icon('arrow')}</button></section><section class="finding-block"><h3>Test a downside scenario</h3><p>Adjust an explicit semiconductor price shock and see its mechanical impact on your portfolio.</p><button class="text-button" data-research="scenario">Open scenario ${icon('arrow')}</button></section></div>${evidence(`<p>Source: local synthetic position. Price return = (${money(h.price)} ÷ ${money(h.cost)} − 1) × 100. Unrealized gain = ${h.qty} × (${money(h.price)} − ${money(h.cost)}). No external research was retrieved.</p>`)}`;
    const cost=h.cost==null?'an unreported cost':money(h.cost,2,h.currency);
    return`<section class="research-question"><h2 class="question-title">${escape(h.name)}: your position in context</h2><p>${qty(h)} with an IBKR cost basis of ${cost} per unit are marked at ${price(h)} in the report of ${L.asOf}. The position accounts for ${pct(positionValue(h)/account.value*100,false)} of your portfolio.</p></section><div class="research-answer"><div><strong class="answer-number num">${pct(growth(h))}</strong><span class="answer-caption">Price return against IBKR cost basis</span></div><div class="answer-side num">${signedMoney(positionGain(h))}<br><span class="small">Unrealized gain · ${escape(D.currency)}</span></div></div><div class="findings-grid"><section class="finding-block"><h3>Exposure</h3><p>${escape(h.name)} is in your ${escape(h.sector)} holdings, held in ${escape(h.currency)}. Fund look-through is not available.</p><button class="text-button" data-research="exposure">View portfolio exposure ${icon('arrow')}</button></section><section class="finding-block"><h3>Test a downside scenario</h3><p>Apply an explicit price decline to this or other holdings and see the mechanical impact.</p><button class="text-button" data-research="scenario">Open scenario ${icon('arrow')}</button></section></div>${evidence(`<p>Source: IBKR Flex report of ${L.asOf}. Price return = (report price ÷ cost per unit − 1) × 100. IBKR’s cost basis includes commissions. Values are converted to ${escape(D.currency)} at the report’s rate.</p>`)}`;
  }
  function purchaseRows(h){
    if(!D.live)return{count:'1 opening purchase',rows:`<tr><td>2026-01-06</td><td>Buy</td><td class="num">${h.qty}</td><td class="num">${money(h.cost)}</td><td class="num">${money(purchaseValue(h))}</td></tr>`,note:'Synthetic opening purchase. No sales, dividends, fees, withholding tax or FX are represented. This history is not an IBKR record.'};
    const trades=h.trades||[];
    return{count:`${trades.length} ${trades.length===1?'trade':'trades'} in imported reports`,rows:trades.length?trades.map(t=>`<tr><td>${escape(t.date)}</td><td>${escape(t.side)}</td><td class="num">${fmtQty(t.qty)}</td><td class="num">${money(t.price,2,t.currency)}</td><td class="num">${money(t.amount,2,t.currency)}</td></tr>`).join(''):'<tr><td colspan="5"><div class="empty-state">No trades for this holding in the imported reports.</div></td></tr>',note:'From your IBKR reports; amounts include commissions. Positions opened before your first imported report have no trade rows here.'};
  }
  function renderStock(){const h=find(state.symbol);if(state.section==='news')return renderStockNews(h);const scope=[h.exchange,h.sector,h.currency].filter(Boolean);const p=purchaseRows(h);return`<div class="breadcrumb"><button data-go="${state.stockOrigins[h.symbol]||'portfolio'}">${names[state.stockOrigins[h.symbol]]||'Portfolio'}</button><span>/</span><span>${escape(h.symbol)}</span></div><header class="canvas-title"><div><div class="stock-title-group"><h1>${escape(h.name)}</h1><span class="ticker">${escape(h.symbol)}</span></div><div class="stock-scope">${scope.map(s=>`<span>${escape(s)}</span>`).join('<span>·</span>')}</div></div><div class="title-actions"><button class="button" data-watch="${escape(h.symbol)}" aria-pressed="${watchlist.includes(h.symbol)}" aria-label="${watchlist.includes(h.symbol)?'Remove':'Add'} ${escape(h.symbol)} ${watchlist.includes(h.symbol)?'from':'to'} watchlist">${icon('star',watchlist.includes(h.symbol)?'fill="currentColor"':'')}<span>${watchlist.includes(h.symbol)?'Following':'Follow'}</span></button></div></header><nav class="subtabs" role="tablist" aria-label="${escape(h.symbol)} sections">${['overview','position','research','news'].map(s=>`<button role="tab" data-stock-section="${escape(s)}" aria-selected="${state.section===s}" tabindex="${state.section===s?0:-1}">${s[0].toUpperCase()+s.slice(1)}</button>`).join('')}</nav>${state.section==='overview'?`<section aria-label="Stock price"><div class="stock-price-row"><span class="stock-price num">${price(h)}</span><span class="daily-change num">${h.previous==null?L.noPrevious:`${signedMoney(h.price-h.previous,h.currency)} (${pct(day(h))}) ${L.vsPrevious}`}</span></div><div class="section-header"><h2>Price & ${D.live?'cost':'purchase cost'}</h2>${D.live?'':periodsHtml(state.stockPeriods[h.symbol]||'YTD','stock')}</div>${!D.live||(h.history||[]).length>=2?'<div id="main-chart" class="chart-wrap stock-chart"></div>':'<div class="chart-empty"><p>The price chart appears once Still has reports for two or more dates.</p></div>'}<p class="chart-caption"><span>${h.cost==null?'No cost reference in the report':`Dashed reference: your ${money(h.cost,2,h.currency)} ${D.live?'average cost':'average purchase'}`}</span><span>${D.live?`IBKR report prices · ${escape(h.currency)}`:'Illustrative history · USD'}</span></p></section>${stockMetrics(h)}<section class="section"><div class="section-header"><h2>Your ${D.live?'position':'purchase'}</h2><button class="text-button" data-stock-section="position">View position & history ${icon('arrow')}</button></div><p class="detail-note">${D.live?`${qty(h)} · cost basis ${money(purchaseValue(h))}. The position is worth ${money(positionValue(h))} in the report of ${L.asOf}. Values in ${escape(D.currency)}.`:`${h.qty} shares · ${money(purchaseValue(h))} invested on 6 Jan 2026. The position is now worth ${money(positionValue(h))}. Price returns exclude dividends, fees, tax and FX.`}</p></section>`:state.section==='position'?`<section aria-labelledby="purchase-comparison-title"><h2 id="purchase-comparison-title">${D.live?'Cost to report price':'Purchase to current price'}</h2><div class="purchase-comparison"><div><p>${D.live?'Average cost · IBKR':'Average purchase · 6 Jan 2026'}</p><strong class="num">${h.cost==null?'—':money(h.cost,2,h.currency)}</strong></div><div class="comparison-bridge"><span class="num">${pct(growth(h))} ${L.sinceCost}</span><svg viewBox="0 0 120 15" fill="none" stroke="currentColor" aria-hidden="true"><path d="M0 7.5h116m-6-5 6 5-6 5"/></svg></div><div><p>${D.live?`Report price · ${L.asOf}`:'Current demo price · 21 Oct 2026'}</p><strong class="num">${price(h)}</strong></div></div>${stockMetrics(h)}</section><section class="section"><div class="section-header"><h2>${D.live?'Trade history':'Purchase history'}</h2><span class="muted small">${p.count}</span></div><div class="table-frame keep-table"><table aria-label="${escape(h.symbol)} ${D.live?'trade':'purchase'} history"><thead><tr><th>Date</th><th>Activity</th><th class="num">${D.live?'Quantity':'Shares'}</th><th class="num">Price</th><th class="num">Amount</th></tr></thead><tbody>${p.rows}</tbody></table></div><p class="detail-note">${p.note}</p></section>`:stockResearch(h)}`;}
  function evidence(body){return`<details class="evidence"><summary>Inputs & calculations</summary>${body}<p>${D.live?`IBKR Flex report of ${L.asOf}. Calculated on this computer; no market feed or model request.`:'Local synthetic dataset · 21 Oct 2026. No live market feed or model request.'}</p></details>`;}
  function researchTabs(){return`<nav class="subtabs" role="tablist" aria-label="Research analysis tabs">${[['exposure','Exposure'],['scenario','Scenarios'],['performance','Performance']].map(([id,label])=>`<button role="tab" data-research="${id}" aria-selected="${state.research===id}" tabindex="${state.research===id?0:-1}">${label}</button>`).join('')}</nav>`;}
  function exposureList(groups,label){return`<div class="exposure-list" aria-label="${label}">${groups.map(([s,v])=>`<div class="exposure-item"><span>${escape(s)}</span><span class="exposure-track"><span style="width:${Math.max(0,v/account.value*100)}%"></span></span><span class="num">${pct(v/account.value*100,false)}</span></div>`).join('')}</div>`;}
  function renderExposure(){
    const grouped={};positions.forEach(h=>grouped[h.sector]=(grouped[h.sector]||0)+positionValue(h));grouped.Cash=account.cash;const groups=Object.entries(grouped).sort((a,b)=>b[1]-a[1]);
    if(!D.live)return`<section class="research-question"><h2 class="question-title">Where is my portfolio concentrated?</h2><p>Technology and semiconductors are your largest combined direct exposure. Cash is included in the portfolio denominator.</p></section><div class="research-answer"><div><strong class="answer-number num">${pct(techValue/account.value*100,false)}</strong><span class="answer-caption">In direct technology & semiconductor positions</span></div><div class="answer-side num">${money(techValue)}<br><span class="small">Across ${technology.length} holdings</span></div></div>${exposureList(groups,'Portfolio allocation by sector')}${evidence(`<p>Sum shares × price within each sector. Divide by total portfolio value, ${money(account.value)}, including ${money(account.cash)} cash. Technology includes MSFT, AAPL and GOOGL; semiconductors includes NVDA and TSM. AMZN is consumer discretionary.</p><p>VTI is a broad market ETF. Its underlying holdings are not available in this demo, so these percentages are direct exposure only and understate any exposure through the ETF.</p>`)}<p class="detail-note">Sector allocation is one view of concentration. It does not measure total investment risk.</p>`;
    const byCurrency={};positions.forEach(h=>byCurrency[h.currency]=(byCurrency[h.currency]||0)+positionValue(h));byCurrency[`Cash (${D.currency})`]=account.cash;const currencies=Object.entries(byCurrency).sort((a,b)=>b[1]-a[1]);
    const top=positions[0],largest=groups[0];
    return`<section class="research-question"><h2 class="question-title">Where is my portfolio concentrated?</h2><p>${top?`Your largest holding is ${escape(top.symbol)} at ${pct(positionValue(top)/account.value*100,false)} of the portfolio. `:''}${escape(largest[0])} is the largest group. Cash is included in the denominator.</p></section><div class="research-answer"><div><strong class="answer-number num">${pct(largest[1]/account.value*100,false)}</strong><span class="answer-caption">In ${escape(largest[0])}</span></div><div class="answer-side num">${money(largest[1])}<br><span class="small">Of ${money(account.value)} total</span></div></div><h2 class="exposure-heading">By asset class</h2>${exposureList(groups,'Portfolio allocation by asset class')}<h2 class="exposure-heading">By currency</h2>${exposureList(currencies,'Portfolio allocation by currency')}${evidence(`<p>Sum position values within each group from the IBKR report of ${L.asOf}, converted to ${escape(D.currency)} at the report’s rates. Divide by total value, ${money(account.value)}, including ${money(account.cash)} cash.</p><p>Funds and ETFs count as single holdings; their underlying exposure is not looked through.</p>`)}<p class="detail-note">Allocation is one view of concentration. It does not measure total investment risk.</p>`;
  }
  function scenarioNumbers(){const lossCents=Math.round(shockedCents()*state.shock/100);return{loss:lossCents/100,after:(cents(account.value)-lossCents)/100,pct:lossCents/cents(account.value)*100};}
  function shockPicker(){return D.live?`<fieldset class="shock-picker"><legend>Holdings to shock</legend>${positions.map(h=>`<button type="button" class="chip ${state.shockSet.includes(h.symbol)?'active':''}" data-shock-toggle="${escape(h.symbol)}" aria-pressed="${state.shockSet.includes(h.symbol)}">${escape(h.symbol)}</button>`).join('')}</fieldset>`:'';}
  function renderScenario(){const n=scenarioNumbers(),list=shocked();const label=D.live?'Price decline':'Semiconductor price decline';return`<section class="research-question"><h2 class="question-title">${D.live?'What if some of your holdings fell?':'What if semiconductor stocks fell?'}</h2><p>${D.live?'Choose holdings and apply the same price decline to each.':'Apply the same price decline to NVDA and TSM.'} Other positions and cash stay unchanged. This is a mechanical scenario, not a forecast.</p></section>${shockPicker()}<div class="scenario-controls"><div><label for="shock-slider">${label}</label><input id="shock-slider" type="range" min="0" max="50" step="1" value="${state.shock}" aria-label="${label} percentage"></div><div><label for="shock-input">Decline</label><div class="shock-number"><input id="shock-input" type="number" min="0" max="50" step="1" value="${state.shock}" aria-label="Price decline percentage"><span>%</span></div></div></div><div id="scenario-result">${scenarioResult(n)}</div><section class="section"><div class="section-header"><h2>Direct positions affected</h2><span class="small muted num">${money(shockedCents()/100)} ${D.live?'selected':'in semiconductors'}</span></div><div class="table-frame keep-table"><table aria-label="${D.live?'Price shock':'Semiconductor scenario'} impact"><thead><tr><th>Holding</th><th class="num">Current value</th><th class="num">Price shock</th><th class="num">Estimated loss</th></tr></thead><tbody id="scenario-rows">${scenarioRows()}</tbody></table></div></section>${evidence(`<p>${D.live?'Selected':'Direct semiconductor'} holdings: ${list.length?list.map(h=>`${escape(h.symbol)}, ${qty(h)} × ${price(h)} = ${money(positionValue(h))}`).join('; '):'none'}.</p><p>Loss = ${money(shockedCents()/100)} × the chosen decline. Post-shock value = ${money(account.value)} − loss. Impact percentage = loss ÷ ${money(account.value)} × 100. All positions are shocked in cents; totals and percentages use the same rounded results.</p>`)}<p class="detail-note">${D.live?'Excludes fund look-through, correlations, FX and second-order price effects.':'Excludes ETF look-through, correlations, FX and second-order price effects. VTI may contain additional semiconductor exposure.'}</p>`;}
  function scenarioResult(n){return`<div class="research-answer"><div><strong class="answer-number num ${n.loss?'negative':'muted'}">${n.loss?'−':''}${money(n.loss)}</strong><span class="answer-caption">Portfolio impact · ${pct(-n.pct)} of current value</span></div><div class="answer-side"><span class="num">${money(n.after)}</span><br><span class="small">Portfolio value after the shock</span></div></div><p class="scenario-baseline"><span>Current portfolio <span class="num">${money(account.value)}</span></span><span>Decline applied <span class="num">${state.shock}%</span></span></p>`;}
  function scenarioRows(){const list=shocked();return list.length?list.map(h=>{const loss=Math.round(cents(positionValue(h))*state.shock/100)/100;return`<tr><td>${escape(h.symbol)}</td><td class="num">${money(positionValue(h))}</td><td class="num">${state.shock?'−':''}${state.shock.toFixed(0)}%</td><td class="num">${loss?'−':''}${money(loss)}</td></tr>`;}).join(''):'<tr><td colspan="4"><div class="empty-state">Choose at least one holding above.</div></td></tr>';}
  function updateShock(raw){const parsed=Number(raw);if(!Number.isFinite(parsed))return;state.shock=Math.min(50,Math.max(0,Math.round(parsed)));$('#shock-slider').value=state.shock;$('#shock-input').value=state.shock;$('#scenario-result').innerHTML=scenarioResult(scenarioNumbers());$('#scenario-rows').innerHTML=scenarioRows();}
  function renderPerformance(){const ranked=positions.filter(h=>growth(h)!=null).sort((a,b)=>growth(b)-growth(a)),h=ranked[0];if(!h)return`<section class="research-question"><h2 class="question-title">Which holding grew the most?</h2><p>Your report has no cost basis for these holdings, so returns cannot be calculated. Include cost basis in the Open Positions section of your Flex query.</p></section>`;return`<section class="research-question"><h2 class="question-title">Which holding grew the most?</h2><p>${escape(h.name)} has the highest percentage price return ${D.live?'against its IBKR cost basis':'from the synthetic purchase date'}. Percentage return and dollar gain answer different questions.</p></section><div class="research-answer"><div><strong class="answer-number num">${pct(growth(h))}</strong><span class="answer-caption">${escape(h.symbol)} · ${D.live?'Price return against cost basis':'Price return since 6 Jan 2026'}</span></div><div class="answer-side num">${signedMoney(positionGain(h))}<br><span class="small">Unrealized gain</span></div></div><section class="section"><div class="section-header"><h2>Returns ${L.sinceCost}</h2><span class="small muted">Ranked by percentage</span></div><div class="table-frame keep-table"><table aria-label="Holdings ranked by return"><thead><tr><th>Company</th><th class="num">${D.live?'Cost':'Purchase'}</th><th class="num">${D.live?'Report price':'Current'}</th><th class="num">Price return</th><th class="num">Unrealized gain</th></tr></thead><tbody>${ranked.map(h=>`<tr class="asset-row" data-open="${escape(h.symbol)}"><td><button class="asset-identity" data-open="${escape(h.symbol)}" aria-label="Open ${escape(h.name)} in a tab"><span class="asset-ticker">${escape(h.symbol)}</span></button></td><td class="num">${money(h.cost,2,h.currency)}</td><td class="num">${price(h)}</td><td class="num">${pct(growth(h))}</td><td class="num">${signedMoney(positionGain(h))}</td></tr>`).join('')}</tbody></table></div></section>${evidence(D.live?`<p>Price return = (report price ÷ cost per unit − 1) × 100. Unrealized gain = position value − cost basis, in ${escape(D.currency)}. IBKR’s cost basis includes commissions; dividends and realized gains are not included.</p>`:`<p>Price return = (current price ÷ purchase price − 1) × 100. Unrealized gain = shares × (current price − purchase price). Each company has one opening purchase; there are no sales, fees, dividends, taxes or FX.</p>`)}`;}
  function unsupported(){return`<section class="research-question"><h2 class="no-match-heading">That question needs more data.</h2><p>Still supports exposure, ${D.live?'a price shock':'a semiconductor shock'} and growth since purchase. It cannot retrieve news, recommend trades or answer arbitrary research questions.</p></section><div class="supported-questions"><button data-research="exposure">Show portfolio exposure ${icon('arrow')}</button><button data-research="scenario">${D.live?'Test a price decline':'Test a semiconductor decline'} ${icon('arrow')}</button><button data-research="performance">Compare growth since purchase ${icon('arrow')}</button></div><p class="detail-note">No external sources or models were queried.</p>`;}
  function renderResearch(){return`${title('Research',D.live?`Portfolio studies · Calculated on this computer · IBKR data as of ${L.asOf}`:'Portfolio studies · Browser calculations · Synthetic data')}${dataBanner()}${researchTabs()}<div id="research-study">${!positions.length?'<div class="empty-state">Your imported report has no open positions to study.</div>':state.unsupported?unsupported():state.research==='scenario'?renderScenario():state.research==='performance'?renderPerformance():renderExposure()}</div><form id="research-composer" class="research-composer"><label for="research-question" class="sr-only">Ask about your ${D.live?'':'demo '}portfolio</label><input id="research-question" autocomplete="off" placeholder="Ask about exposure, a shock, or price growth…"><button type="submit" class="button" aria-label="Run ${D.live?'portfolio':'demo'} research">${icon('send')}Ask</button></form><p class="detail-note">Answers use fixed templates and your ${D.live?'imported':'demo'} positions. No live AI or investment recommendations.</p>`;}
  function renderStockNews(h){return`<div class="breadcrumb"><button data-go="${state.stockOrigins[h.symbol]||'portfolio'}">${names[state.stockOrigins[h.symbol]]||'Portfolio'}</button><span>/</span><span>${escape(h.symbol)}</span></div>${title(h.name,`${h.symbol} · Public company research`)}<nav class="subtabs" role="tablist" aria-label="${escape(h.symbol)} sections">${['overview','position','research','news'].map(s=>`<button role="tab" data-stock-section="${escape(s)}" aria-selected="${state.section===s}" tabindex="${state.section===s?0:-1}">${s[0].toUpperCase()+s.slice(1)}</button>`).join('')}</nav><div id="news-content"></div>`;}
  function renderNews(){return`${title('News','Primary-source releases & finance search')}<nav class="subtabs" role="tablist" aria-label="News sections">${[['feed','Feed'],['search','Search'],['sources','Sources']].map(([key,label])=>`<button role="tab" data-news-mode="${key}" aria-selected="${state.news===key}" tabindex="${state.news===key?0:-1}">${label}</button>`).join('')}</nav><div id="news-content"></div>`;}
  const settingsTabs=[['ibkr','IBKR connection'],['search','News search'],['security','Security'],['privacy','Data & privacy']];
  function renderSettings(){return`${title('Settings',ctx.server?'Everything here is saved encrypted on this computer':'Personal workspace')}<nav class="subtabs" role="tablist" aria-label="Settings sections">${settingsTabs.map(([key,label])=>`<button id="settings-tab-${key}" role="tab" data-setting="${key}" aria-controls="settings-content" aria-selected="${state.settings===key}" tabindex="${state.settings===key?0:-1}">${label}</button>`).join('')}</nav><div id="settings-content" role="tabpanel" aria-labelledby="settings-tab-${state.settings}"></div>`;}

  function renderCanvas(){
    window.StillNews.unmount();
    window.StillSettings.unmount();
    $$('.chart-wrap').forEach(el=>el._chartObserver?.disconnect());
    const body=state.tab==='portfolio'?renderPortfolio():state.tab==='discover'?renderDiscover():state.tab==='stock'?renderStock():state.tab==='research'?renderResearch():state.tab==='news'?renderNews():renderSettings();
    $('#canvas-content').innerHTML=`<div class="content">${body}</div>`;
    drawCurrentChart();
    if($('#news-content'))window.StillNews.mount($('#news-content'),{mode:state.tab==='stock'?'search':state.news,company:state.tab==='stock'?`${find(state.symbol).name} ${state.symbol}`:''});
    if($('#settings-content'))window.StillSettings.mount($('#settings-content'),{tab:state.settings,context:ctx,data:D});
  }
  function seeded(seed){return()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646;};}
  function chartData(h,p){const end=h?h.price:account.value;const multipliers={'1W':.016,'1M':.047,'3M':.093};const start=p==='1D'?(h?h.previous:account.value-account.day):p==='YTD'||p==='ALL'?(h?h.cost:account.basis+account.cash):end/(1+multipliers[p]*(h?1.3:1));const count=p==='1D'?49:97;const random=seeded((h?h.seed:97)+periods.indexOf(p)*17),walk=[0];for(let i=1;i<count;i++)walk.push(walk[i-1]+random()-.48);const values=walk.map((v,i)=>{const t=i/(count-1);return start+(end-start)*t+(v-walk[count-1]*t)*end*.008*Math.sin(Math.PI*t);});const endDate=new Date('2026-10-21T16:00:00Z'),startDate=new Date(endDate);if(p==='1D')startDate.setUTCHours(9,30);else if(p==='1W')startDate.setUTCDate(14);else if(p==='1M')startDate.setUTCMonth(8);else if(p==='3M')startDate.setUTCMonth(6);else startDate.setTime(new Date('2026-01-06T16:00:00Z').getTime());const labels=values.map((_,i)=>{const date=new Date(startDate.getTime()+(endDate-startDate)*i/(count-1));return new Intl.DateTimeFormat('en-US',p==='1D'?{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'UTC'}:{day:'numeric',month:'short',timeZone:'UTC'}).format(date);});return{values,labels,start,end};}
  function liveChartData(h){const points=h?(h.history||[]).map(r=>({date:r.date,value:r.price})):D.history;const values=points.map(r=>r.value);return{values,labels:points.map(r=>fmtDate(r.date)),start:values[0],end:values.at(-1)};}
  function drawCurrentChart(){const el=$('#main-chart');if(!el||!el.clientWidth)return;const h=state.tab==='stock'?find(state.symbol):null,p=h?(state.stockPeriods[h.symbol]||'YTD'):state.period;const d=D.live?liveChartData(h):chartData(h,p);const format=h?v=>money(v,2,h.currency):money;const ref=h?h.cost:account.basis==null?null:account.basis+account.cash;const min=Math.min(...d.values,ref??Infinity);const scale=Math.max(...d.values,ref??-Infinity)-min||Math.abs(min)*.1||1;window.Charts.line(el,{labels:d.labels,series:[{name:h?`${h.symbol} ${D.live?'report price':'synthetic price'}`:D.live?'Portfolio value':'Synthetic portfolio value',values:d.values}],format,tickFormat:h?v=>money(v,0,h.currency):v=>`${Math.round(v/1000)}k`,height:()=>el.clientHeight||252,min:min-scale*.12,...(ref==null?{}:{reference:{value:ref,label:h?(D.live?'Average cost':'Average purchase'):(D.live?'Cost basis + cash':'Opening cost + cash')}}),fill:false});if(!h){const delta=d.end-d.start;$('#portfolio-period-change').textContent=D.live?`${signedMoney(delta)} (${pct(delta/d.start*100)}) · ${fmtDate(D.history[0].date)} to ${L.asOf}`:`${signedMoney(delta)} (${pct(delta/d.start*100)}) · ${({'1D':'vs previous close','1W':'past week','1M':'past month','3M':'past 3 months','YTD':'year to date','ALL':'since opening purchase'})[p]}`;}}
  function syncFilters(){
    if($('#instrument-search').value!==state.query)$('#instrument-search').value=state.query;
    if($('#discover-search')&&$('#discover-search').value!==state.query)$('#discover-search').value=state.query;
    if(state.tab==='research')renderBrowser();else renderInstrumentRows();
    if(state.tab==='portfolio')$('#main-holdings').innerHTML=holdingsTable();
    if(state.tab==='discover')$('#main-discover').innerHTML=holdingsTable(true);
  }
  function toggleWatch(symbol){if(!find(symbol))return;watchlist=watchlist.includes(symbol)?watchlist.filter(s=>s!==symbol):[...watchlist,symbol];const saved=save(localStorage,'still.watchlist',watchlist);renderBrowser();const scroll=$('#workspace-panel').scrollTop;renderCanvas();$('#workspace-panel').scrollTop=scroll;toast(saved?`${symbol} ${watchlist.includes(symbol)?'added to':'removed from'} watchlist`:'Watchlist updated for this session; browser storage is unavailable.');}
  function closeStock(symbol){if(symbol==='settings'){navigate('portfolio');return;}const index=openStocks.indexOf(symbol);openStocks=openStocks.filter(s=>s!==symbol);persistTabs();if(state.tab==='stock'&&state.symbol===symbol){const next=openStocks[Math.max(0,index-1)];navigate(next?`stock/${next}`:'portfolio',{focus:true});}else renderShell();}
  function ask(text){const q=text.trim().toLowerCase();if(!q)return;state.unsupported='';if(/semiconductor|shock|20%|decline|fall/.test(q))state.research='scenario';else if(/grow|growth|perform|best|gain/.test(q))state.research='performance';else if(/expos|concentr|sector|divers/.test(q))state.research='exposure';else state.unsupported=q;state.query='';navigate('research',{resetScroll:true,focus:true});$('#quick-question-input').value='';}
  function globalSearch(){const q=$('#global-search').value.toLowerCase().trim();globalItems=[...['portfolio','discover','research','news','settings'].map(key=>({id:key,label:names[key],sub:'Workspace',run:()=>navigate(key,{focus:true})})),...positions.map(h=>({id:h.symbol,label:`${h.symbol} · ${h.name}`,sub:'Open stock tab',run:()=>navigate(`stock/${h.symbol}`,{focus:true})}))].filter(item=>item.label.toLowerCase().includes(q));globalIndex=0;renderGlobalResults();}
  function renderGlobalResults(){const wrap=$('#global-results');wrap.hidden=false;$('#global-search').setAttribute('aria-expanded','true');wrap.innerHTML=globalItems.length?globalItems.map((r,i)=>`<button class="search-result ${i===globalIndex?'selected':''}" id="global-option-${i}" role="option" aria-selected="${i===globalIndex}" data-global="${i}" tabindex="-1"><span>${escape(r.label)}</span><small>${escape(r.sub)}</small></button>`).join(''):'<p class="search-empty">No matches. Try a company name or symbol.</p>';if(globalItems.length)$('#global-search').setAttribute('aria-activedescendant',`global-option-${globalIndex}`);else $('#global-search').removeAttribute('aria-activedescendant');}
  function closeGlobal(){ $('#global-results').hidden=true;$('#global-search').setAttribute('aria-expanded','false');$('#global-search').removeAttribute('aria-activedescendant');}
  function runGlobal(index){const item=globalItems[index];if(item){closeGlobal();$('#global-search').value='';item.run();}}
  function setListWidth(value,persist=true){const width=Math.min(440,Math.max(240,Math.round(value)));$('#app').style.setProperty('--list-width',width+'px');$('#splitter').setAttribute('aria-valuenow',String(width));if(persist)save(localStorage,'still.listWidth',width);}
  function resetFilters(){state.query='';state.sector='all';state.listMode='holdings';state.gainers=false;renderBrowser();renderCanvas();}
  document.addEventListener('click',event=>{
    const button=event.target.closest('button');
    if(button?.dataset.go)navigate(button.dataset.go);
    if(button?.dataset.open)navigate('stock/'+button.dataset.open,{focus:true});
    if(!button){const row=event.target.closest('tr[data-open]');if(row)navigate('stock/'+row.dataset.open,{focus:true});}
    if(button?.dataset.close)closeStock(button.dataset.close);
    if(button?.dataset.watch)toggleWatch(button.dataset.watch);
    if(button?.dataset.newsMode){navigate('news',{news:button.dataset.newsMode,resetScroll:true});$(`[data-news-mode="${state.news}"]`)?.focus({preventScroll:true});}
    if(button?.dataset.setting){navigate('settings',{settings:button.dataset.setting,resetScroll:true});$(`[data-setting="${state.settings}"]`)?.focus({preventScroll:true});}
    if(button?.dataset.stockSection){state.stockSections[state.symbol]=button.dataset.stockSection;navigate(`stock/${state.symbol}/${button.dataset.stockSection}`,{resetScroll:true});$(`[data-stock-section="${state.section}"]`)?.focus({preventScroll:true});}
    if(button?.dataset.research){state.unsupported='';if(state.tab==='research')state.query='';state.queries.research='';navigate('research',{research:button.dataset.research,resetScroll:true});$(`#canvas-content [data-research="${state.research}"]`)?.focus({preventScroll:true});}
    if(button?.dataset.period){if(button.dataset.periodScope==='portfolio')state.period=button.dataset.period;else state.stockPeriods[state.symbol]=button.dataset.period;renderCanvas();$(`[data-period="${button.dataset.period}"]`)?.focus({preventScroll:true});}
    if(button?.dataset.list){state.listMode=button.dataset.list;renderBrowser();renderCanvas();$(`#canvas-content [data-list="${state.listMode}"]`)?.focus({preventScroll:true});}
    if(button?.dataset.gainers!==undefined){state.gainers=button.dataset.gainers==='true';renderBrowser();renderCanvas();}
    if(button?.dataset.sort){state.direction=state.sort===button.dataset.sort?-state.direction:1;state.sort=button.dataset.sort;renderCanvas();$(`[data-sort="${state.sort}"]`)?.focus({preventScroll:true});}
    if(button?.hasAttribute('data-clear'))resetFilters();
    if(button?.dataset.shockToggle){const s=button.dataset.shockToggle;state.shockSet=state.shockSet.includes(s)?state.shockSet.filter(x=>x!==s):[...state.shockSet,s];renderCanvas();$(`[data-shock-toggle="${CSS.escape(s)}"]`)?.focus({preventScroll:true});}
    if(button?.dataset.global!==undefined)runGlobal(Number(button.dataset.global));
    if(!event.target.closest('.global-search-wrap'))closeGlobal();
    if(button?.id==='reset-preferences'){watchlist=['NVDA','MSFT','AAPL'];save(localStorage,'still.watchlist',watchlist);setListWidth(300);state.collapsed=false;$('#app').classList.remove('collapsed');renderBrowser();toast('Workspace preferences reset.');}
  });
  document.addEventListener('input',event=>{const el=event.target;if(el.id==='instrument-search'||el.id==='discover-search'){state.query=el.value;syncFilters();}if(el.id==='global-search')globalSearch();if(el.id==='shock-slider'||el.id==='shock-input')updateShock(el.value);});
  document.addEventListener('change',event=>{if(event.target.id==='browser-sector'||event.target.id==='discover-sector'){state.sector=event.target.value;renderBrowser();renderCanvas();}});
  document.addEventListener('submit',event=>{if(event.target.id==='quick-question'){event.preventDefault();ask($('#quick-question-input').value);}if(event.target.id==='research-composer'){event.preventDefault();ask($('#research-question').value);}});
  $('#global-search').addEventListener('focus',globalSearch);
  $('#global-search').addEventListener('keydown',event=>{if(event.key==='Escape'){closeGlobal();event.target.blur();return;}if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if(globalItems.length){globalIndex=(globalIndex+(event.key==='ArrowDown'?1:-1)+globalItems.length)%globalItems.length;renderGlobalResults();$('.search-result.selected')?.scrollIntoView({block:'nearest'});}}if(event.key==='Enter'){event.preventDefault();runGlobal(globalIndex);}});
  $('#new-tab').onclick=()=>{navigate('discover');state.collapsed=false;$('#app').classList.remove('collapsed');(matchMedia('(max-width:700px)').matches?$('#discover-search'):$('#instrument-search')).focus();};
  $('#toggle-list').onclick=()=>{state.collapsed=!state.collapsed;$('#app').classList.toggle('collapsed',state.collapsed);$('#toggle-list').setAttribute('aria-expanded',String(!state.collapsed));$('#toggle-list').setAttribute('aria-label',state.collapsed?'Show instrument list':'Hide instrument list');};
  const separator=$('#splitter');separator.addEventListener('pointerdown',event=>{if(event.button!==0)return;dragging=true;separator.setPointerCapture(event.pointerId);document.body.classList.add('resizing');event.preventDefault();});separator.addEventListener('pointermove',event=>{if(dragging)setListWidth(event.clientX-56,false);});
  const endDrag=()=>{if(!dragging)return;dragging=false;document.body.classList.remove('resizing');save(localStorage,'still.listWidth',Number(separator.getAttribute('aria-valuenow')));};separator.addEventListener('pointerup',endDrag);separator.addEventListener('pointercancel',endDrag);
  separator.addEventListener('keydown',event=>{const old=Number(separator.getAttribute('aria-valuenow'));if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();setListWidth(event.key==='Home'?240:event.key==='End'?440:old+(event.key==='ArrowRight'?16:-16));}});
  document.addEventListener('keydown',event=>{
    if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#global-search').focus();globalSearch();return;}
    const tab=event.target.closest('[role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){const list=tab.closest('[role=tablist]');if(list){const buttons=$$('[role=tab]',list),index=buttons.indexOf(tab);const target=event.key==='Home'?buttons[0]:event.key==='End'?buttons.at(-1):buttons[(index+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length];event.preventDefault();const key=target.dataset.go||target.dataset.stockSection||target.dataset.research||target.dataset.newsMode||target.dataset.setting||target.dataset.list;target.click();const selector=target.dataset.go?`[role=tab][data-go="${key}"]`:target.dataset.stockSection?`[role=tab][data-stock-section="${key}"]`:target.dataset.research?`#canvas-content [role=tab][data-research="${key}"]`:target.dataset.newsMode?`[role=tab][data-news-mode="${key}"]`:target.dataset.setting?`[role=tab][data-setting="${key}"]`:`[role=tab][data-list="${key}"]`;$(selector)?.focus({preventScroll:true});return;}}
    if(/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)||event.metaKey||event.ctrlKey||event.altKey)return;
    if(event.key==='/'){event.preventDefault();if(state.tab==='research'){state.query='';navigate('discover');}if(state.collapsed){state.collapsed=false;$('#app').classList.remove('collapsed');}if(matchMedia('(max-width:700px)').matches){if(state.tab!=='discover')navigate('discover');$('#discover-search').focus();}else $('#instrument-search').focus();}
    if(['1','2','3','4'].includes(event.key))navigate(['portfolio','discover','research','news'][Number(event.key)-1]);
    if(event.key==='Delete'&&tab?.dataset.go?.startsWith('stock/'))closeStock(tab.dataset.go.split('/')[1]);
  });
  window.addEventListener('popstate',()=>{const r=readRoute();navigate(r.tab==='stock'?`stock/${r.symbol}/${r.section}`:r.tab,{history:true,research:r.research,settings:r.settings,news:r.news});});
  window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!==route()){const r=readRoute();navigate(r.tab==='stock'?`stock/${r.symbol}/${r.section}`:r.tab,{history:true,research:r.research,settings:r.settings,news:r.news});}});
  function renderStatus(){
    const counts=D.reconciliation?.counts;
    $('.demo-status').innerHTML=`<span></span>${D.live?`IBKR · ${L.asOf}`:'Synthetic data'}`;
    $('.statusbar>span').innerHTML=D.live?`<span class="connection-dot live"></span>IBKR report ${L.asOf} <span class="status-separator">/</span> ${counts?`${counts.pass} checks passed${counts.fail?` · ${counts.fail} failed`:''}${counts.unverified?` · ${counts.unverified} need review`:''}`:'Not reconciled'}`:`<span class="connection-dot"></span>Demo workspace <span class="status-separator">/</span> ${ctx.server?'Connect IBKR in Settings':'No broker connected'}`;
    $('.statusbar>span:nth-child(2)').innerHTML=`${escape(D.currency)} <span class="status-separator">·</span> Calculations run locally`;
    $('.browser-footer>p').textContent=D.live?`IBKR report · ${L.asOf}`:'Demo snapshot · 21 Oct 2026';
  }
  renderStatus();
  const width=Number(read(localStorage,'still.listWidth',300));setListWidth(Number.isFinite(width)?width:300,false);
  Object.assign(state,readRoute());navigate(state.tab==='stock'?`stock/${state.symbol}/${state.section}`:state.tab,{history:true});
});
